<?php
$cartId=(int)$cart['account']['id'];$editable=$cart['account']['status']==='open'&&permissionRecord('restaurante.accounts',$cartId,'edit');
?>
<div class="restaurant-pos-ticket-head"><div><p class="eyebrow">PEDIDO</p><h2><?= $h($cart['account']['name']) ?></h2></div><span class="restaurant-state"><?= ($page['preview']??false)?'Libre':($cart['account']['status']==='closed'?(!empty($cart['header']['invoice_id'])?'Pagada':'Cerrada'):'En atención') ?></span></div>
<?php if(!$cart['items']): ?><div class="restaurant-pos-cart-empty"><span aria-hidden="true">＋</span><h3>Agrega el primer producto</h3><p><?= ($page['preview']??false)?'La mesa se ocupa al agregar el primer producto. Si vuelves sin agregar nada, seguirá libre.':'Toca los productos de la carta para cargarlos a esta mesa.' ?></p></div><?php endif; ?>
<div class="restaurant-pos-lines">
<?php foreach($cart['items'] as $item): ?><article class="restaurant-pos-line"><div class="restaurant-pos-line-title"><strong><?= $h($item['product_name']) ?></strong><strong><?= $h($item['total_amount']) ?></strong></div><small><?= $h($item['unit_price'].' '.$cart['currency']) ?> por unidad<?php if(bccomp($item['tax_rate'],'0',4)>0): ?> · Impuesto <?= $h(rtrim(rtrim($item['tax_rate'],'0'),'.')) ?> %<?php endif; ?></small>
<?php if($editable): ?><div class="restaurant-pos-line-controls">
<?php $minus=bcsub($item['quantity'],'1',3);foreach([['−',bccomp($minus,'0',3)>0?'pos_quantity':'pos_remove',$minus],['+','pos_quantity',bcadd($item['quantity'],'1',3)]] as [$label,$action,$quantity]): ?>
<form method="post" data-pos-command><?php restaurantPosFields($cart,$action); ?><input type="hidden" name="item_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="quantity" value="<?= $h($quantity) ?>"><button type="submit" aria-label="<?= $label==='+'?'Aumentar':'Reducir' ?> <?= $h($item['product_name']) ?>"><?= $label ?></button></form><?php if($label==='−'): ?><span><?= $h(rtrim(rtrim($item['quantity'],'0'),'.')) ?></span><?php endif; ?>
<?php endforeach; ?><form method="post" data-pos-command class="restaurant-pos-remove"><?php restaurantPosFields($cart,'pos_remove'); ?><input type="hidden" name="item_id" value="<?= (int)$item['id'] ?>"><button type="submit" aria-label="Quitar <?= $h($item['product_name']) ?>">Quitar</button></form></div>
<details class="restaurant-pos-note"><summary><?= $item['notes']?$h($item['notes']):'Agregar observación' ?></summary><form method="post" data-pos-command><?php restaurantPosFields($cart,'pos_note'); ?><input type="hidden" name="item_id" value="<?= (int)$item['id'] ?>"><label>Observación<input name="notes" maxlength="255" value="<?= $h($item['notes']) ?>" placeholder="Sin cebolla, salsa aparte…"></label><button type="submit">Guardar</button></form></details>
<?php else: ?><p><?= $h($item['quantity'].' unidades'.($item['notes']?' · '.$item['notes']:'')) ?></p><?php endif; ?></article><?php endforeach; ?></div>
<div class="restaurant-pos-totals"><div><span>Subtotal</span><strong><?= $h($cart['base']) ?></strong></div><div><span>Impuestos</span><strong><?= $h($cart['tax']) ?></strong></div><div class="restaurant-pos-grand-total"><span>Total</span><strong><?= $h($cart['total'].' '.$cart['currency']) ?></strong></div></div>
<?php if($cart['account']['status']==='closed' && !empty($cart['header']['invoice_id'])): ?><div class="restaurant-notice" role="status">Factura emitida y cobro registrado.</div><a class="button button-primary" href="../contabilidad/index.php?type=customer&amp;id=<?= (int)$cart['header']['invoice_id'] ?>">Ver factura</a><a class="button" href="index.php">Volver a las mesas</a>
<?php elseif(empty($page['preview'])&&$cart['account']['status']==='open'&&permissionRecord('restaurante.accounts',$cartId,'confirm')&&permissionRecord('restaurante.accounts',$cartId,'pay')): ?><button type="button" class="button button-primary restaurant-pos-checkout" data-pos-open-checkout <?= !$cart['items']?'disabled':'' ?>>Facturar y cobrar</button><?php endif; ?>
